$ErrorActionPreference = "Stop"
$root = (Get-Location).Path
if (!(Test-Path -LiteralPath (Join-Path $root "app.py"))) { throw "Run from project root" }
$backup = Join-Path $root (".security-backup/" + [guid]::NewGuid().ToString())
if ((Get-FileHash -LiteralPath (Join-Path $root "app.py")).Hash -ne "06468b2185f3956c41d021cbb2d6d1cfb3235b3a38ae5f96a934497df9adf84b") { throw "Original file differs: app.py" }
if ((Get-FileHash -LiteralPath (Join-Path $root "infrastructure/file_readers.py")).Hash -ne "7f8e2c7609b72ad8a2011284dd759b5897371269dadef147188e9d277ed7bd05") { throw "Original file differs: infrastructure/file_readers.py" }
