$b = Join-Path $backup ".gitignore"
if (Test-Path -LiteralPath $p) { New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null; Copy-Item -LiteralPath $p -Destination $b }
New-Item -ItemType Directory -Force -Path (Split-Path $p) | Out-Null
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String("LmVudgouZW52LioKIS5lbnYuZXhhbXBsZQoudmVudi8KX19weWNhY2hlX18vCi5weXRlc3RfY2FjaGUvCmRhdGEvCiouaWNzCiouc3FsaXRlMwoKKi5kYgoqLnNxbGl0ZQoqLnB5Ywouc2VjdXJpdHktYmFja3VwLwo="))
$p = Join-Path $root ".streamlit/config.toml"
$b = Join-Path $backup ".streamlit/config.toml"
if (Test-Path -LiteralPath $p) { New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null; Copy-Item -LiteralPath $p -Destination $b }
New-Item -ItemType Directory -Force -Path (Split-Path $p) | Out-Null
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String("W3NlcnZlcl0KYWRkcmVzcyA9ICIxMjcuMC4wLjEiCm1heFVwbG9hZFNpemUgPSAxMApbYnJvd3Nlcl0KZ2F0aGVyVXNhZ2VTdGF0cyA9IGZhbHNlCg=="))
